#!/usr/bin/env node
/**
 * Test driver: boot the external-implementer composition, run the
 * training-eligible environments once each with the `spawn` subagent provider
 * as the implementer, run the same environments again on their own model route,
 * and print both fleet reports, the delegation events each delegated cell
 * session recorded, the facts of the certified delegated cell, and the
 * scoreboard folded from every persisted log, for the e2e's assertions.
 */

import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type { EnvironmentDelegation } from '@deepseek-ai/dsh-environment-runner/types'
import type { FleetCellOutcome, FleetPlan } from '@deepseek-ai/dsh-fleet/types'
import type { SessionId } from '@deepseek-ai/dsh-session'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('external-implementer driver requires a config path')

const ctx = await boot('external-implementer-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates agents only over the settled application.
  await ctx.get('loader')?.await()
  const fleet = ctx.get('fleet')
  const scorekeeper = ctx.get('scorekeeper')
  const persistence = ctx.get('sessionPersistence')
  if (fleet === undefined || scorekeeper === undefined || persistence === undefined) {
    throw new Error('external-implementer driver requires the fleet, the scorekeeper, and session persistence')
  }
  const plan = (group: string, implementer?: FleetPlan['implementer']): FleetPlan => ({
    environments: { filter: { heldOut: false } },
    models: [],
    repetitions: 1,
    workspaceRoot: process.cwd(),
    group,
    ...implementer === undefined ? {} : { implementer },
  })
  const delegated = await fleet.run(plan('external-implementer-e2e', { kind: 'subagent', provider: 'spawn', label: 'external' }))
  const routed = await fleet.run(plan('route-implementer-e2e'))

  const sessionOf = (outcome: FleetCellOutcome): SessionId => {
    if (!('report' in outcome)) throw new Error(`cell ${outcome.cell.environment} produced no report`)
    return outcome.report.sessionId
  }
  const delegations: Record<string, EnvironmentDelegation[]> = {}
  for (const outcome of delegated.cells) {
    const { events } = await persistence.inspect(sessionOf(outcome))
    delegations[outcome.cell.environment] = events.flatMap(event => (
      event.type === 'environment/delegation' ? [event.data] : []
    ))
  }

  const certified = delegated.cells.find(outcome => 'report' in outcome && outcome.report.certified)
  if (certified === undefined) throw new Error('external-implementer driver expects one certified delegated cell')
  const facts = await scorekeeper.facts(sessionOf(certified))
  const scoreboard = await scorekeeper.leaderboard({})
  process.stdout.write(`${JSON.stringify({
    type: 'result',
    delegated: { leaderboard: delegated.leaderboard, stamps: delegated.cells.map(outcome => ('report' in outcome ? outcome.report.stamp : null)) },
    routed: { leaderboard: routed.leaderboard },
    delegations,
    facts,
    scoreboard,
  })}\n`)
} finally {
  await ctx.fiber.dispose()
}

import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import type { EnvironmentDelegation, EnvironmentRunStamp } from '@deepseek-ai/dsh-environment-runner/types'
import type { LeaderboardRow } from '@deepseek-ai/dsh-fleet/types'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'
import type { ScoreboardBatch, SessionFactsRecord } from '@deepseek-ai/dsh-scorekeeper/types'

const binScript = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/external-implementer/driver.ts', import.meta.url))
const configPath = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/external-implementer/cordis.yml', import.meta.url))
const repoTsconfig = fileURLToPath(new URL('../../../../tsconfig.json', import.meta.url))

interface DriverResult {
  type: string
  delegated: { leaderboard: LeaderboardRow[]; stamps: (EnvironmentRunStamp | null)[] }
  routed: { leaderboard: LeaderboardRow[] }
  delegations: Record<string, EnvironmentDelegation[]>
  facts: SessionFactsRecord
  scoreboard: ScoreboardBatch
}

describe('a delegated cell through a real cordis.yml and headless process', () => {
  it('implements every attempt on the subagent provider and certifies on the tree it left', async () => {
    const { stdout, stderr } = await runLoaderSmoke({
      label: 'external-implementer',
      tempDirPrefix: 'external-implementer-e2e-',
      binScript,
      libBinScript: binScript,
      configPath,
      binArgs: [configPath],
      tsconfigPath: repoTsconfig,
    })
    expect(stderr).toBe('')
    const result = JSON.parse(stdout.trimEnd().split('\n').at(-1) ?? '') as DriverResult
    expect(result.type).toBe('result')

    // The runner ran the checks itself on the tree the delegated child left.
    expect(result.delegated.leaderboard.map(row => [row.environmentId, row.implementer, row.certified, row.attemptsMean])).toEqual([
      ['smoke:round-trip', 'spawn', 1, 1],
      ['smoke:unsatisfiable', 'spawn', 0, 2],
    ])
    expect(result.delegated.stamps.map(stamp => stamp?.implementer)).toEqual(['spawn', 'spawn'])
    expect(result.routed.leaderboard.map(row => row.implementer)).toEqual(['route', 'route'])

    // One child run per attempt, the second carrying the directive the first produced.
    expect(result.delegations['smoke:round-trip']).toEqual([
      { attempt: 1, provider: 'spawn', runId: expect.any(String) as unknown as string, stopReason: 'completed', usage: expect.any(Object) as unknown as object },
    ])
    const failing = result.delegations['smoke:unsatisfiable'] ?? []
    expect(failing.map(delegation => [delegation.attempt, delegation.provider, delegation.stopReason]))
      .toEqual([[1, 'spawn', 'completed'], [2, 'spawn', 'completed']])
    expect(new Set(failing.map(delegation => delegation.runId)).size).toBe(2)

    // The cell session carries the delegation records and no model turn of its own.
    expect(result.facts.identity.environment).toMatchObject({ environmentId: 'smoke:round-trip', implementer: 'spawn' })
    expect(result.facts.outcome).toMatchObject({ reward: 1, rewardBasis: 'certificate', certified: true, certificateExecutor: 'runner' })
    expect(result.facts.efficiency.inputTokens).toBe(0)

    // Two implementers on one environment are two rows the scoreboard never merges.
    const roundTrip = result.scoreboard.rows.filter(row => row.environmentId === 'smoke:round-trip')
    expect(roundTrip.map(row => [row.implementer, row.certified, row.runs])).toEqual([['spawn', 1, 1], ['route', 1, 1]])
    // The delegated children are sessions of their own that no runner stamped.
    expect(result.scoreboard.unstamped).toBeGreaterThan(0)
  }, LOADER_SMOKE_TEST_TIMEOUT_MS)
})

