#!/usr/bin/env node
/**
 * Driver: boot the village-claude-implementer composition, run one fleet plan
 * of the two training-eligible smoke environments with the real Claude Code
 * product as the implementer of every cell, then fold the publication side —
 * the observatory page and document, the exported session facts, and the
 * exported trajectories — and print the report, the delegation records, both
 * export reports, and the document.
 */

import { writeFile } from 'node:fs/promises'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type { EnvironmentDelegation } from '@deepseek-ai/dsh-environment-runner/types'
import type {} from '@deepseek-ai/dsh-fleet'
import type {} from '@deepseek-ai/dsh-observatory'
import type {} from '@deepseek-ai/dsh-scorekeeper'
import { jsonlFileSink } from '@deepseek-ai/dsh-trajectories'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('village-claude-implementer driver requires a config path')

const ctx = await boot('village-claude-implementer', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates agents only over the settled application.
  await ctx.get('loader')?.await()
  const fleet = ctx.get('fleet')
  const observatory = ctx.get('observatory')
  const scorekeeper = ctx.get('scorekeeper')
  const trajectories = ctx.get('trajectories')
  const persistence = ctx.get('sessionPersistence')
  if (fleet === undefined || observatory === undefined || scorekeeper === undefined
    || trajectories === undefined || persistence === undefined) {
    throw new Error('village-claude-implementer requires the fleet, observatory, scorekeeper, trajectories, and persistence services')
  }
  const report = await fleet.run({
    environments: { filter: { heldOut: false } },
    models: [],
    repetitions: 1,
    workspaceRoot: process.cwd(),
    group: 'village-claude-implementer',
    district: 'proving-ground',
    implementer: { kind: 'subagent', provider: 'claude-code', label: 'external' },
  })

  const delegations: Record<string, EnvironmentDelegation[]> = {}
  for (const outcome of report.cells) {
    if (!('report' in outcome)) continue
    const { events } = await persistence.inspect(outcome.report.sessionId)
    delegations[outcome.cell.environment] = events.flatMap(event => (
      event.type === 'environment/delegation' ? [event.data] : []
    ))
  }

  const snapshot = await observatory.snapshot()
  const page = observatory.render(snapshot, Date.now())
  await writeFile('observatory.html', page.html)
  await writeFile('observatory.json', `${JSON.stringify(page.json, null, 2)}\n`)
  const facts = await scorekeeper.exportFacts({ sink: jsonlFileSink('./facts.jsonl') })
  const exported = await trajectories.export({ sink: jsonlFileSink('./trajectories.jsonl') })
  process.stdout.write(`${JSON.stringify({
    type: 'result',
    report,
    delegations,
    facts,
    exported,
    document: page.json,
  })}\n`)
} finally {
  await ctx.fiber.dispose()
}

/**
 * With-key style e2e: it drives the REAL Claude Code product on the host's own
 * installation and account, so it self-skips unless `DSH_E2E_CLAUDE_CODE=1` is
 * set and is run by hand. Nothing in CI holds that authentication, and the run
 * costs the host's own product quota; `docs/testing.md` owns the key policy this
 * follows.
 */

import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import type { EnvironmentDelegation } from '@deepseek-ai/dsh-environment-runner/types'
import type { FleetRunReport } from '@deepseek-ai/dsh-fleet/types'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'
import type { ObservatoryDocument } from '@deepseek-ai/dsh-observatory/types'
import type { FactsExportReport } from '@deepseek-ai/dsh-scorekeeper/types'
import type { TrajectoryExportReport } from '@deepseek-ai/dsh-trajectories/types'

const binScript = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/village-claude-implementer/driver.ts', import.meta.url))
const configPath = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/village-claude-implementer/cordis.yml', import.meta.url))
const repoTsconfig = fileURLToPath(new URL('../../../../tsconfig.json', import.meta.url))

interface DriverResult {
  type: string
  report: FleetRunReport
  delegations: Record<string, EnvironmentDelegation[]>
  facts: FactsExportReport
  exported: TrajectoryExportReport
  document: ObservatoryDocument
}

describe.skipIf(process.env.DSH_E2E_CLAUDE_CODE !== '1')('the Proving Ground with the real product as implementer', () => {
  it('delegates every attempt to the product and certifies on the trees it left', async () => {
    let observatory = ''
    const { stdout, stderr } = await runLoaderSmoke({
      label: 'village-claude-implementer',
      tempDirPrefix: 'village-claude-implementer-e2e-',
      binScript,
      libBinScript: binScript,
      configPath,
      binArgs: [configPath],
      tsconfigPath: repoTsconfig,
      inspect: async (cwd) => {
        observatory = await readFile(join(cwd, 'observatory.html'), 'utf8')
      },
    })
    expect(stderr).toBe('')
    const result = JSON.parse(stdout.trimEnd().split('\n').at(-1) ?? '') as DriverResult
    expect(result.type).toBe('result')

    // Every cell reached the runner and was stamped with the product provider.
    expect(result.report.cells).toHaveLength(2)
    const stamps = result.report.cells.flatMap(outcome => ('report' in outcome ? [outcome.report.stamp] : []))
    expect(stamps).toHaveLength(2)
    expect(stamps.map(stamp => stamp.implementer)).toEqual(['claude-code', 'claude-code'])
    expect(result.report.leaderboard.map(row => row.implementer)).toEqual(['claude-code', 'claude-code'])

    // One child run per attempt, each recorded durably in the cell session.
    for (const outcome of result.report.cells) {
      if (!('report' in outcome)) continue
      const recorded = result.delegations[outcome.cell.environment] ?? []
      expect(recorded.map(delegation => delegation.attempt)).toEqual(outcome.report.attempts.map(attempt => attempt.attempt))
